package com.flippingfriend.companion;
/** Immutable production-equivalent round-trip completion probability evidence. */
final class BuyReplacementRoundTripCompletionEvaluation {
 private final BuyReplacementSellFillViableCandidate source; private final double completionProbability;
 BuyReplacementRoundTripCompletionEvaluation(BuyReplacementSellFillViableCandidate s,double p){source=s;completionProbability=p;}
 int getBuyOffsetIndex(){return source.getBuyOffsetIndex();} double getBuyOffset(){return source.getBuyOffset();} int getBuyPrice(){return source.getBuyPrice();} int getExactRemainderQuantity(){return source.getExactRemainderQuantity();} long getTotalCost(){return source.getTotalCost();} double getBuyProbability(){return source.getBuyProbability();} double getBuyExpectedHours(){return source.getBuyExpectedHours();} double getBuyUnitsPerHour(){return source.getBuyUnitsPerHour();} double getBuyWaitHours(){return source.getBuyWaitHours();} int getSellOffsetIndex(){return source.getSellOffsetIndex();} double getSellOffset(){return source.getSellOffset();} int getSellPrice(){return source.getSellPrice();} long getRawSpreadPerItem(){return source.getRawSpreadPerItem();} int getTaxPerItem(){return source.getTaxPerItem();} long getNetMarginPerItem(){return source.getNetMarginPerItem();} long getTotalTax(){return source.getTotalTax();} long getTotalNetMargin(){return source.getTotalNetMargin();} double getSellProbability(){return source.getSellProbability();} double getSellExpectedHours(){return source.getSellExpectedHours();} double getSellUnitsPerHour(){return source.getSellUnitsPerHour();} double getSellWaitHours(){return source.getSellWaitHours();} double getCompletionProbability(){return completionProbability;}
}
